export {
  closeButtonClasses as shadcnToastCloseButtonClasses,
  containerClasses as shadcnToastContainerClasses,
  descriptionClasses as shadcnToastDescriptionClasses,
  entryClasses as shadcnToastEntryClasses,
  titleClasses as shadcnToastTitleClasses,
  toastClasses as shadcnToastClasses,
  toastEntryView as shadcnToastEntryView,
} from "../../../foldkit/ui/toast/view";

import { describe, expect, test } from "vitest";

import * as Toast from "./index";

describe("shadcn Toast registry view", () => {
  test("reuses the Foldkit Toast functional contract", () => {
    expect(Toast.init).toBeTypeOf("function");
    expect(Toast.show).toBeTypeOf("function");
    expect(Toast.shadcnToastEntryView).toBeTypeOf("function");
    expect(Toast.shadcnToastClasses).toContain("data-[closed]");
  });
});
